import{_ as p,a0 as r,w as u,s as o,I as i,x as n,a1 as a,A as l,ao as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"将树莓派 3B+ 变为 PriTunl VPN | LCTT x X-CMD","titleTemplate":false,"description":"将树莓派 3B+ 变为 PriTunl VPN | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将树莓派 3B+ 变为 PriTunl VPN | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将树莓派 3B+ 变为 PriTunl VPN | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20190114 Turn a Raspberry Pi 3B- into a PriTunl VPN","title":"将树莓派 3B+ 变为 PriTunl VPN","tag":"201901","desc":""},"relativePath":"201901/20190114 Turn a Raspberry Pi 3B- into a PriTunl VPN.md","filePath":"[post].md"}'),d={name:"201901/20190114 Turn a Raspberry Pi 3B- into a PriTunl VPN.md"};function g(b,s,h,k,m,f){const t=r("Link");return u(),o("div",null,[s[23]||(s[23]=i("h1",{id:"将树莓派-3b-变为-pritunl-vpn",tabindex:"-1"},[n("将树莓派 3B+ 变为 PriTunl VPN "),i("a",{class:"header-anchor",href:"#将树莓派-3b-变为-pritunl-vpn","aria-label":"Permalink to “将树莓派 3B+ 变为 PriTunl VPN”"},"​")],-1)),s[24]||(s[24]=i("blockquote",null,[i("p",null,"PriTunl 是一种 VPN 解决方案，适用于希望私密的访问其网络的小型企业和个人。")],-1)),s[25]||(s[25]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/life-raspberrypi_0.png?itok=Kczz87J2",alt:""})],-1)),i("p",null,[a(t,{href:"https://pritunl.com/"},{default:l(()=>[...s[0]||(s[0]=[n("PriTunl",-1)])]),_:1}),s[1]||(s[1]=n(" 是一款出色的 VPN 终端解决方案，非常适合希望以简单快捷的方式私密的访问网络的小型企业和个人。它是开源的，基本的免费版本涵盖最通用的简单的实例，足以让你快速入门。也有集成了活动目录等高级功能的付费企业版。",-1))]),s[26]||(s[26]=e('<h3 id="有关树莓派-3b-的特别注意事项" tabindex="-1">有关树莓派 3B+ 的特别注意事项 <a class="header-anchor" href="#有关树莓派-3b-的特别注意事项" aria-label="Permalink to “有关树莓派 3B+ 的特别注意事项”">​</a></h3><p>PriTunl 的安装通常也很简单，但要在树莓派 3B+ 上安装 PriTunl 有点小复杂。比如，PriTunl 只提供了 AMD64 和 i386 架构的二进制文件，但树莓派 3B+ 是 ARM 架构的，这意味着需要从源码自行编译可用于树莓派 3B+ 的 PriTunl 可执行文件。不过，无需担心，编译过程很简单，只需花一点时间执行几行命令即可。</p><p>另一个问题：PriTunl 好像必须要是 64 位处理器架构，当我在 32 位操作系统上尝试编译的时候报错了。但幸运的是，用于 ARM64 架构的 Ubuntu 18.04 测试版本可以安装在树莓派 3B+ 上。</p><p>同样，树莓派 3B+ 需要和其他树莓派不同的引导程序。需要一组小复杂的命令来安装更新树莓派 3B+ 上必要的组件。</p><h3 id="安装-pritunl" tabindex="-1">安装 PriTunl <a class="header-anchor" href="#安装-pritunl" aria-label="Permalink to “安装 PriTunl”">​</a></h3><p>你可以先在树莓派 3B+ 上安装 64 位的操作系统来避免下面这些问题。此处需要一些必要的基础知识如在树莓派上执行命令行。</p><p>打开终端，用如下命令下载 Ubuntu 18.04 用于 ARM64 架构的测试版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://cdimage.ubuntu.com/releases/18.04/beta/ubuntu-18.04-beta-preinstalled-server-arm64+raspi3.img.xz</span></span></code></pre></div><p>将下载的固件解压：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xz -d ubuntu-18.04-beta-preinstalled-server-arm64+raspi3.xz</span></span></code></pre></div><p>将准备好的 SD 卡插入电脑读卡槽，电脑会为 SD 卡分配一个驱动分配器号，例如 <code>/dev/sda</code> 或者 <code>/dev/sdb</code>。 输入命令 <code>dmesg</code> 然后观察屏幕上的最后几行找到 SD 卡的驱动分配器。</p><p><strong>下一步小心操作，如果搞错了驱动分配器号，可能会破坏你的系统。</strong></p><p>用如下命令往 SD 卡中写入数据，将其中的 <code>&lt;DRIVE&gt;</code> 替换成你的 SD 驱动器号。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dd if=ubuntu-18.04-beta-preinstalled-server-arm64+raspi3.img of=&lt;DRIVE&gt; bs=8M</span></span></code></pre></div><p>完成上一步之后，将 SD 卡插入树莓派 3B+ ，并启动它。确保树莓派 3B+ 是连网的，然后登录系统，用户名/密码：<code>ubuntu</code> / <code>ubuntu</code>。</p><p>在树莓派上输入以下命令以安装一些编译 PriTunl 所需的包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get -y install build-essential git bzr python python-dev python-pip net-tools openvpn bridge-utils psmisc golang-go libffi-dev mongodb</span></span></code></pre></div>',17)),i("p",null,[s[3]||(s[3]=n("和 PriTunl 标准源码上的 ",-1)),a(t,{href:"https://github.com/pritunl/pritunl"},{default:l(()=>[...s[2]||(s[2]=[n("安装说明",-1)])]),_:1}),s[4]||(s[4]=n(" 有一点不一样。确保已经登录进树莓派然后切换到管理员账户：",-1))]),s[27]||(s[27]=e(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo su -</span></span></code></pre></div><p>现在你应该在管理员账户的目录下，按如下命令来安装 PriTunl 1.29.1914.98 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export VERSION=1.29.1914.98</span></span>
<span class="line"><span>tee -a ~/.bashrc &lt;&lt; EOF</span></span>
<span class="line"><span>export GOPATH=\\$HOME/go</span></span>
<span class="line"><span>export PATH=/usr/local/go/bin:\\$PATH</span></span>
<span class="line"><span>EOF</span></span>
<span class="line"><span>source ~/.bashrc</span></span>
<span class="line"><span>mkdir pritunl &amp;&amp; cd pritunl</span></span>
<span class="line"><span>go get -u github.com/pritunl/pritunl-dns</span></span>
<span class="line"><span>go get -u github.com/pritunl/pritunl-web</span></span>
<span class="line"><span>sudo ln -s ~/go/bin/pritunl-dns /usr/bin/pritunl-dns</span></span>
<span class="line"><span>sudo ln -s ~/go/bin/pritunl-web /usr/bin/pritunl-web</span></span>
<span class="line"><span>wget https://github.com/pritunl/pritunl/archive/$VERSION.tar.gz</span></span>
<span class="line"><span>tar -xf $VERSION.tar.gz</span></span>
<span class="line"><span>cd pritunl-$VERSION</span></span>
<span class="line"><span>python2 setup.py build</span></span>
<span class="line"><span>pip install -r requirements.txt</span></span>
<span class="line"><span>python2 setup.py install --prefix=/usr/local</span></span></code></pre></div><p>现在，不出意外的话应该可以启动 MongoDB 和 PriTunl 的 systemd 单元了。假如现在还是以管理员账户登录的话，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl daemon-reload</span></span>
<span class="line"><span>systemctl start mongodb pritunl</span></span>
<span class="line"><span>systemctl enable mongodb pritunl</span></span></code></pre></div>`,5)),i("p",null,[s[6]||(s[6]=n("大功告成！你现在可以登录 PriTunl 的用户界面并按照官网上的 ",-1)),a(t,{href:"https://docs.pritunl.com/docs/configuration-5"},{default:l(()=>[...s[5]||(s[5]=[n("安装和配置手册",-1)])]),_:1}),s[7]||(s[7]=n(" 来配置它了。",-1))]),s[28]||(s[28]=i("hr",null,null,-1)),i("p",null,[s[9]||(s[9]=n("via: ",-1)),a(t,{href:"https://opensource.com/article/19/1/pritunl-vpn-raspberry-pi"},{default:l(()=>[...s[8]||(s[8]=[n("https://opensource.com/article/19/1/pritunl-vpn-raspberry-pi",-1)])]),_:1})]),i("p",null,[s[14]||(s[14]=n("作者：",-1)),a(t,{href:"https://opensource.com/users/stevereaver"},{default:l(()=>[...s[10]||(s[10]=[n("Stephen Bancroft",-1)])]),_:1}),s[15]||(s[15]=n(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[11]||(s[11]=[n("lujun9972",-1)])]),_:1}),s[16]||(s[16]=n(" 译者：",-1)),a(t,{href:"https://github.com/jrglinux"},{default:l(()=>[...s[12]||(s[12]=[n("jrg",-1)])]),_:1}),s[17]||(s[17]=n(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...s[13]||(s[13]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[20]||(s[20]=n("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[18]||(s[18]=[n("LCTT",-1)])]),_:1}),s[21]||(s[21]=n(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...s[19]||(s[19]=[n("Linux中国",-1)])]),_:1}),s[22]||(s[22]=n(" 荣誉推出",-1))])])}const y=p(d,[["render",g]]);export{c as __pageData,y as default};
